/// True only for the NodeFrame variants this module owns. Callers must invoke
/// this after the connection challenge moved to `Authenticated`.
pub(super) fn is_supervisor_frame(frame: &v1::NodeFrame) -> bool {
    matches!(
        &frame.frame,
        Some(
            v1::node_frame::Frame::SupervisorRegistration(_)
                | v1::node_frame::Frame::SupervisorHeartbeat(_)
                | v1::node_frame::Frame::SupervisorSession(_)
                | v1::node_frame::Frame::SupervisorLifecycleReceipt(_)
        )
    )
}

/// The legacy NodeSync constructor has no supervisor store. It must refuse a
/// typed supervisor fact as temporarily unavailable rather than treating it
/// as an invalid connection frame or pretending it was persisted.
pub(super) fn unavailable_frame() -> v1::AckplaneFrame {
    rejection(IngressError::Unavailable(
        "supervisor ingestion is not configured for this NodeSync service",
    ))
}

/// Handles one typed supervisor fact under the tenant/repository/node identity
/// established by the active NodeSync connection. The wire's node id never
/// selects authority: it must match the already-authenticated producer.
pub(super) async fn handle_authenticated_frame(
    frame: v1::NodeFrame,
    tenant_id: &str,
    repository_id: &str,
    node_id: &str,
    store: &mut SupervisorStore,
) -> Vec<v1::AckplaneFrame> {
    let Some(frame) = frame.frame else {
        return Vec::new();
    };
    let outcome = match frame {
        v1::node_frame::Frame::SupervisorRegistration(wire) => {
            registration_receipt(wire, tenant_id, repository_id, node_id, store).await
        }
        v1::node_frame::Frame::SupervisorHeartbeat(wire) => {
            let supervisor_id = wire.supervisor_id.clone();
            store
                .record_heartbeat(tenant_id, repository_id, &supervisor_id)
                .await
                .map(|_| {
                    receipt(
                        v1::SupervisorFrameOperation::Heartbeat,
                        &supervisor_id,
                        "",
                        false,
                        false,
                        None,
                    )
                })
                .map_err(IngressError::from)
        }
        v1::node_frame::Frame::SupervisorSession(wire) => {
            let supervisor_id = wire.supervisor_id.clone();
            let session_id = wire.session_id.clone();
            match session_from_wire(wire) {
                Ok(session) => store
                    .record_session(tenant_id, repository_id, &session)
                    .await
                    .map(|outcome| {
                        receipt(
                            v1::SupervisorFrameOperation::Session,
                            &supervisor_id,
                            &session_id,
                            outcome.idempotent_replay,
                            !outcome.idempotent_replay,
                            None,
                        )
                    })
                    .map_err(IngressError::from),
                Err(error) => Err(error),
            }
        }
        v1::node_frame::Frame::SupervisorLifecycleReceipt(wire) => {
            let supervisor_id = wire.supervisor_id.clone();
            let session_id = wire.session_id.clone();
            match lifecycle_from_wire(wire, tenant_id, repository_id) {
                Ok(request) => store
                    .record_lifecycle(&request)
                    .await
                    .map(|outcome| {
                        receipt(
                            v1::SupervisorFrameOperation::Lifecycle,
                            &supervisor_id,
                            &session_id,
                            outcome.idempotent_replay,
                            outcome.projection_advanced,
                            None,
                        )
                    })
                    .map_err(IngressError::from),
                Err(error) => Err(error),
            }
        }
        _ => return Vec::new(),
    };
    match outcome {
        Ok(receipt) => vec![v1::AckplaneFrame {
            frame: Some(v1::ackplane_frame::Frame::SupervisorFrameReceipt(receipt)),
        }],
        Err(error) => vec![rejection(error)],
    }
}

fn registration_from_wire(
    wire: v1::SupervisorRegistration,
    tenant_id: &str,
    repository_id: &str,
    authenticated_node_id: &str,
) -> Result<ContractRegistration, IngressError> {
    if wire.node_id != authenticated_node_id {
        return Err(IngressError::Unauthorized(
            "supervisor registration node_id does not match the authenticated connection",
        ));
    }
    Ok(ContractRegistration {
        supervisor_id: wire.supervisor_id,
        identity: SupervisorIdentity {
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            node_id: authenticated_node_id.to_string(),
        },
        supervisor_version: wire.supervisor_version,
        protocol_version: wire.protocol_version,
        capabilities: SupervisorCapabilities {
            supported_directives: wire
                .supported_directives
                .into_iter()
                .map(directive_capability_from_wire)
                .collect::<Result<Vec<_>, _>>()?,
            supports_checkpoint: wire.supports_checkpoint,
            supports_force_termination: wire.supports_force_termination,
            outbox_durability: outbox_durability_from_wire(wire.outbox_durability)?,
            recoverable_outbox: wire.recoverable_outbox,
        },
    })
}

fn session_from_wire(wire: v1::SupervisorSession) -> Result<ContractSession, IngressError> {
    Ok(ContractSession {
        session_id: wire.session_id,
        supervisor_id: wire.supervisor_id,
        worker_id: wire.worker_id,
        runtime: runtime_from_wire(wire.runtime)?,
        started_at: parse_unix_seconds(&wire.started_at, "started_at")?,
        state: worker_state_from_wire(wire.state)?,
    })
}

fn lifecycle_from_wire(
    wire: v1::SupervisorLifecycleReceipt,
    tenant_id: &str,
    repository_id: &str,
) -> Result<SupervisorLifecycleReceiptRequest, IngressError> {
    let reason = match v1::SupervisorLifecycleReason::try_from(wire.reason) {
        Ok(v1::SupervisorLifecycleReason::Unspecified) => None,
        Ok(value) => Some(lifecycle_reason_from_wire(value)?),
        Err(_) => return Err(IngressError::Malformed("lifecycle reason is unknown")),
    };
    Ok(SupervisorLifecycleReceiptRequest {
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        receipt: ContractLifecycleReceipt {
            supervisor_id: wire.supervisor_id,
            session_id: wire.session_id,
            worker_id: wire.worker_id,
            occurred_at: parse_unix_seconds(&wire.occurred_at, "occurred_at")?,
            state: worker_state_from_wire(wire.state)?,
            reason,
        },
        idempotency_key: wire.idempotency_key,
    })
}

fn directive_capability_from_wire(value: i32) -> Result<ContractDirectiveCapability, IngressError> {
    match v1::SupervisorDirectiveCapability::try_from(value) {
        Ok(v1::SupervisorDirectiveCapability::Notify) => Ok(ContractDirectiveCapability::Notify),
        Ok(v1::SupervisorDirectiveCapability::Prompt) => Ok(ContractDirectiveCapability::Prompt),
        Ok(v1::SupervisorDirectiveCapability::Assign) => Ok(ContractDirectiveCapability::Assign),
        Ok(v1::SupervisorDirectiveCapability::Steer) => Ok(ContractDirectiveCapability::Steer),
        Ok(v1::SupervisorDirectiveCapability::Pause) => Ok(ContractDirectiveCapability::Pause),
        Ok(v1::SupervisorDirectiveCapability::Resume) => Ok(ContractDirectiveCapability::Resume),
        Ok(v1::SupervisorDirectiveCapability::Drain) => Ok(ContractDirectiveCapability::Drain),
        Ok(v1::SupervisorDirectiveCapability::TerminateGracefully) => {
            Ok(ContractDirectiveCapability::TerminateGracefully)
        }
        Ok(v1::SupervisorDirectiveCapability::TerminateForce) => {
            Ok(ContractDirectiveCapability::TerminateForce)
        }
        Ok(v1::SupervisorDirectiveCapability::Unspecified) | Err(_) => Err(
            IngressError::Malformed("supervisor directive capability is unknown"),
        ),
    }
}

fn outbox_durability_from_wire(value: i32) -> Result<ContractOutboxDurability, IngressError> {
    match v1::SupervisorOutboxDurability::try_from(value) {
        Ok(v1::SupervisorOutboxDurability::Persistent) => Ok(ContractOutboxDurability::Persistent),
        Ok(v1::SupervisorOutboxDurability::Ephemeral) => Ok(ContractOutboxDurability::Ephemeral),
        Ok(v1::SupervisorOutboxDurability::Unspecified) | Err(_) => Err(IngressError::Malformed(
            "supervisor outbox durability is unknown",
        )),
    }
}

fn runtime_from_wire(value: i32) -> Result<ContractRuntime, IngressError> {
    match v1::SupervisorRuntime::try_from(value) {
        Ok(v1::SupervisorRuntime::LocalMachine) => Ok(ContractRuntime::LocalMachine),
        Ok(v1::SupervisorRuntime::CloudWorker) => Ok(ContractRuntime::CloudWorker),
        Ok(v1::SupervisorRuntime::Pipeline) => Ok(ContractRuntime::Pipeline),
        Ok(v1::SupervisorRuntime::Service) => Ok(ContractRuntime::Service),
        Ok(v1::SupervisorRuntime::Unspecified) | Err(_) => {
            Err(IngressError::Malformed("supervisor runtime is unknown"))
        }
    }
}

fn worker_state_from_wire(value: i32) -> Result<ContractWorkerState, IngressError> {
    match v1::SupervisorWorkerState::try_from(value) {
        Ok(v1::SupervisorWorkerState::Started) => Ok(ContractWorkerState::Started),
        Ok(v1::SupervisorWorkerState::Checkpointed) => Ok(ContractWorkerState::Checkpointed),
        Ok(v1::SupervisorWorkerState::Paused) => Ok(ContractWorkerState::Paused),
        Ok(v1::SupervisorWorkerState::Draining) => Ok(ContractWorkerState::Draining),
        Ok(v1::SupervisorWorkerState::Terminated) => Ok(ContractWorkerState::Terminated),
        Ok(v1::SupervisorWorkerState::Failed) => Ok(ContractWorkerState::Failed),
        Ok(v1::SupervisorWorkerState::Disconnected) => Ok(ContractWorkerState::Disconnected),
        Ok(v1::SupervisorWorkerState::Reconnected) => Ok(ContractWorkerState::Reconnected),
        Ok(v1::SupervisorWorkerState::Completed) => Ok(ContractWorkerState::Completed),
        Ok(v1::SupervisorWorkerState::Unspecified) | Err(_) => Err(IngressError::Malformed(
            "supervisor worker state is unknown",
        )),
    }
}

fn lifecycle_reason_from_wire(
    value: v1::SupervisorLifecycleReason,
) -> Result<ContractLifecycleReason, IngressError> {
    match value {
        v1::SupervisorLifecycleReason::CapabilityMissing => {
            Ok(ContractLifecycleReason::CapabilityMissing)
        }
        v1::SupervisorLifecycleReason::CheckpointFailed => {
            Ok(ContractLifecycleReason::CheckpointFailed)
        }
        v1::SupervisorLifecycleReason::DirectiveExpired => {
            Ok(ContractLifecycleReason::DirectiveExpired)
        }
        v1::SupervisorLifecycleReason::OutboxUnavailable => {
            Ok(ContractLifecycleReason::OutboxUnavailable)
        }
        v1::SupervisorLifecycleReason::ProtocolUnsupported => {
            Ok(ContractLifecycleReason::ProtocolUnsupported)
        }
        v1::SupervisorLifecycleReason::SupervisorFailed => {
            Ok(ContractLifecycleReason::SupervisorFailed)
        }
        v1::SupervisorLifecycleReason::WorkerLost => Ok(ContractLifecycleReason::WorkerLost),
        v1::SupervisorLifecycleReason::Unspecified => Err(IngressError::Malformed(
            "supervisor lifecycle reason is unknown",
        )),
    }
}

fn parse_unix_seconds(value: &str, field: &'static str) -> Result<i64, IngressError> {
    let timestamp = OffsetDateTime::parse(value, &Rfc3339)
        .map_err(|_| IngressError::Malformed(field))?
        .unix_timestamp();
    if timestamp < 0 {
        return Err(IngressError::Malformed(field));
    }
    Ok(timestamp)
}

/// Registers a supervisor and answers with the position this server
/// independently holds for it (ADR-0141, via ADR-0146 decision 4).
///
/// A free function rather than an inline arm because it is genuinely two
/// sequential awaits over the store, and the `.map(|outcome| ...)` closure the
/// other arms use cannot await the second one.
///
/// The position is read *after* the registration commits, so a supervisor that
/// is registering for the first time gets this server's honest answer for it
/// rather than one computed against a supervisor it had not yet accepted.
async fn registration_receipt(
    wire: v1::SupervisorRegistration,
    tenant_id: &str,
    repository_id: &str,
    node_id: &str,
    store: &mut SupervisorStore,
) -> Result<v1::SupervisorFrameReceipt, IngressError> {
    let supervisor_id = wire.supervisor_id.clone();
    let registration = registration_from_wire(wire, tenant_id, repository_id, node_id)?;
    let outcome = store.register(&registration).await?;
    let accepted_outbox_sequence = store
        .accepted_outbox_sequence(tenant_id, repository_id, &supervisor_id)
        .await?;
    Ok(receipt(
        v1::SupervisorFrameOperation::Registration,
        &supervisor_id,
        "",
        outcome.idempotent_replay,
        !outcome.idempotent_replay,
        accepted_outbox_sequence,
    ))
}

fn receipt(
    operation: v1::SupervisorFrameOperation,
    supervisor_id: &str,
    session_id: &str,
    idempotent_replay: bool,
    projection_advanced: bool,
    accepted_outbox_sequence: Option<u64>,
) -> v1::SupervisorFrameReceipt {
    v1::SupervisorFrameReceipt {
        operation: operation as i32,
        supervisor_id: supervisor_id.to_string(),
        session_id: session_id.to_string(),
        idempotent_replay,
        projection_advanced,
        // `None` for every frame that is not outbox-carried. Heartbeat,
        // session, and lifecycle frames advance nothing (ADR-0146 decision 2),
        // and nothing reads a position from their receipts, so answering with
        // one would cost a store round trip per heartbeat to restate a number
        // the registration receipt already carried.
        accepted_outbox_sequence,
    }
}

fn rejection(error: IngressError) -> v1::AckplaneFrame {
    let (reason, retryable, diagnostic) = match error {
        IngressError::Malformed(diagnostic) => (v1::RejectionReason::Malformed, false, diagnostic),
        IngressError::Unauthorized(diagnostic) => {
            (v1::RejectionReason::Unauthorized, false, diagnostic)
        }
        IngressError::Unavailable(diagnostic) => {
            (v1::RejectionReason::Unavailable, true, diagnostic)
        }
    };
    v1::AckplaneFrame {
        frame: Some(v1::ackplane_frame::Frame::Rejection(v1::Rejection {
            record_id: String::new(),
            reason: reason as i32,
            retryable,
            diagnostic: diagnostic.to_string(),
        })),
    }
}

#[derive(Debug)]
enum IngressError {
    Malformed(&'static str),
    Unauthorized(&'static str),
    Unavailable(&'static str),
}

impl From<SupervisorStoreError> for IngressError {
    fn from(error: SupervisorStoreError) -> Self {
        match error {
            SupervisorStoreError::Database(_) => {
                Self::Unavailable("supervisor store is temporarily unavailable")
            }
            SupervisorStoreError::UnknownSupervisor
            | SupervisorStoreError::UnknownSession
            | SupervisorStoreError::SessionIdentityMismatch => {
                Self::Unauthorized("supervisor fact is outside the authenticated session identity")
            }
            _ => Self::Malformed("supervisor fact is invalid or conflicts with durable state"),
        }
    }
}

#[cfg(test)]
mod tests {
    use ackplane_protocol::v1;

    use super::*;

    fn unique_suffix() -> String {
        let mut bytes = [0_u8; 8];
        getrandom::getrandom(&mut bytes).expect("the OS random source should be available");
        bytes.iter().map(|byte| format!("{byte:02x}")).collect()
    }

    fn registration_frame(supervisor_id: &str, node_id: &str) -> v1::NodeFrame {
        v1::NodeFrame {
            frame: Some(v1::node_frame::Frame::SupervisorRegistration(
                v1::SupervisorRegistration {
                    supervisor_id: supervisor_id.to_string(),
                    node_id: node_id.to_string(),
                    supervisor_version: "supervisor:v1".to_string(),
                    protocol_version: "v1".to_string(),
                    supported_directives: vec![v1::SupervisorDirectiveCapability::Notify as i32],
                    supports_checkpoint: true,
                    supports_force_termination: false,
                    outbox_durability: v1::SupervisorOutboxDurability::Persistent as i32,
                    recoverable_outbox: true,
                },
            )),
        }
    }

    fn supervisor_receipt(frames: Vec<v1::AckplaneFrame>) -> v1::SupervisorFrameReceipt {
        match frames.as_slice() {
            [v1::AckplaneFrame {
                frame: Some(v1::ackplane_frame::Frame::SupervisorFrameReceipt(receipt)),
            }] => receipt.clone(),
            other => panic!("expected one supervisor frame receipt, got {other:?}"),
        }
    }

    fn rejection(frames: Vec<v1::AckplaneFrame>) -> v1::Rejection {
        match frames.as_slice() {
            [v1::AckplaneFrame {
                frame: Some(v1::ackplane_frame::Frame::Rejection(rejection)),
            }] => rejection.clone(),
            other => panic!("expected one NodeSync rejection, got {other:?}"),
        }
    }

    async fn store() -> Option<SupervisorStore> {
        let database_url = std::env::var("ACKPLANE_TEST_DATABASE_URL").ok()?;
        Some(SupervisorStore::connect(&database_url).await.unwrap())
    }

    #[test]
    fn supervisor_facts_are_retryably_unavailable_without_a_configured_store() {
        assert_eq!(
            unavailable_frame(),
            v1::AckplaneFrame {
                frame: Some(v1::ackplane_frame::Frame::Rejection(v1::Rejection {
                    record_id: String::new(),
                    reason: v1::RejectionReason::Unavailable as i32,
                    retryable: true,
                    diagnostic: "supervisor ingestion is not configured for this NodeSync service"
                        .to_string(),
                })),
            }
        );
    }

    #[tokio::test]
    async fn malformed_supervisor_session_time_is_refused_before_persistence() {
        let Some(mut store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let suffix = unique_suffix();
        let tenant_id = format!("tenant-supervisor-time-{suffix}");
        let repository_id = format!("repository-supervisor-time-{suffix}");
        let node_id = format!("node-{suffix}");
        let supervisor_id = format!("supervisor-{suffix}");
        let response = handle_authenticated_frame(
            v1::NodeFrame {
                frame: Some(v1::node_frame::Frame::SupervisorSession(
                    v1::SupervisorSession {
                        supervisor_id,
                        session_id: format!("session-{suffix}"),
                        worker_id: format!("worker-{suffix}"),
                        runtime: v1::SupervisorRuntime::Service as i32,
                        started_at: "not-an-rfc3339-timestamp".to_string(),
                        state: v1::SupervisorWorkerState::Started as i32,
                    },
                )),
            },
            &tenant_id,
            &repository_id,
            &node_id,
            &mut store,
        )
        .await;

        assert_eq!(
            rejection(response),
            v1::Rejection {
                record_id: String::new(),
                reason: v1::RejectionReason::Malformed as i32,
                retryable: false,
                diagnostic: "started_at".to_string(),
            }
        );
        assert_eq!(
            store
                .list_supervisors(&tenant_id, &repository_id)
                .await
                .expect("read scope after malformed session"),
            Vec::new()
        );
    }

    #[tokio::test]
    async fn supervisor_registration_refuses_a_node_other_than_the_authenticated_connection() {
        let Some(mut store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let suffix = unique_suffix();
        let tenant_id = format!("tenant-supervisor-frame-{suffix}");
        let repository_id = format!("repository-supervisor-frame-{suffix}");
        let supervisor_id = format!("supervisor-{suffix}");
        let response = handle_authenticated_frame(
            registration_frame(&supervisor_id, "node-other"),
            &tenant_id,
            &repository_id,
            "node-authenticated",
            &mut store,
        )
        .await;

        assert_eq!(
            rejection(response),
            v1::Rejection {
                record_id: String::new(),
                reason: v1::RejectionReason::Unauthorized as i32,
                retryable: false,
                diagnostic:
                    "supervisor registration node_id does not match the authenticated connection"
                        .to_string(),
            }
        );
        assert_eq!(
            store
                .list_supervisors(&tenant_id, &repository_id)
                .await
                .expect("read supervisor scope after refusal"),
            Vec::new()
        );
    }

    #[tokio::test]
    async fn authenticated_supervisor_frames_persist_and_replay_lifecycle_facts() {
        let Some(mut store) = store().await else {
            println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
            return;
        };
        let suffix = unique_suffix();
        let tenant_id = format!("tenant-supervisor-frame-{suffix}");
        let repository_id = format!("repository-supervisor-frame-{suffix}");
        let node_id = format!("node-{suffix}");
        let supervisor_id = format!("supervisor-{suffix}");
        let session_id = format!("session-{suffix}");
        let worker_id = format!("worker-{suffix}");

        let registration = supervisor_receipt(
            handle_authenticated_frame(
                registration_frame(&supervisor_id, &node_id),
                &tenant_id,
                &repository_id,
                &node_id,
                &mut store,
            )
            .await,
        );
        assert_eq!(
            registration,
            v1::SupervisorFrameReceipt {
                operation: v1::SupervisorFrameOperation::Registration as i32,
                supervisor_id: supervisor_id.clone(),
                session_id: String::new(),
                idempotent_replay: false,
                projection_advanced: true,
                // Nothing sequenced has been accepted from this supervisor, so
                // the server states no position (ADR-0146 decision 5).
                accepted_outbox_sequence: None,
            }
        );

        let heartbeat = supervisor_receipt(
            handle_authenticated_frame(
                v1::NodeFrame {
                    frame: Some(v1::node_frame::Frame::SupervisorHeartbeat(
                        v1::SupervisorHeartbeat {
                            supervisor_id: supervisor_id.clone(),
                        },
                    )),
                },
                &tenant_id,
                &repository_id,
                &node_id,
                &mut store,
            )
            .await,
        );
        assert_eq!(
            heartbeat,
            v1::SupervisorFrameReceipt {
                operation: v1::SupervisorFrameOperation::Heartbeat as i32,
                supervisor_id: supervisor_id.clone(),
                session_id: String::new(),
                idempotent_replay: false,
                projection_advanced: false,
                accepted_outbox_sequence: None,
            }
        );

        let session = supervisor_receipt(
            handle_authenticated_frame(
                v1::NodeFrame {
                    frame: Some(v1::node_frame::Frame::SupervisorSession(
                        v1::SupervisorSession {
                            supervisor_id: supervisor_id.clone(),
                            session_id: session_id.clone(),
                            worker_id: worker_id.clone(),
                            runtime: v1::SupervisorRuntime::Service as i32,
                            started_at: "2026-01-01T00:00:00Z".to_string(),
                            state: v1::SupervisorWorkerState::Started as i32,
                        },
                    )),
                },
                &tenant_id,
                &repository_id,
                &node_id,
                &mut store,
            )
            .await,
        );
        assert_eq!(
            session,
            v1::SupervisorFrameReceipt {
                operation: v1::SupervisorFrameOperation::Session as i32,
                supervisor_id: supervisor_id.clone(),
                session_id: session_id.clone(),
                idempotent_replay: false,
                projection_advanced: true,
                accepted_outbox_sequence: None,
            }
        );

        let lifecycle_frame = v1::NodeFrame {
            frame: Some(v1::node_frame::Frame::SupervisorLifecycleReceipt(
                v1::SupervisorLifecycleReceipt {
                    supervisor_id: supervisor_id.clone(),
                    session_id: session_id.clone(),
                    worker_id: worker_id.clone(),
                    occurred_at: "2026-01-01T00:00:10Z".to_string(),
                    state: v1::SupervisorWorkerState::Paused as i32,
                    reason: v1::SupervisorLifecycleReason::DirectiveExpired as i32,
                    idempotency_key: format!("receipt-{suffix}"),
                },
            )),
        };
        let lifecycle = supervisor_receipt(
            handle_authenticated_frame(
                lifecycle_frame.clone(),
                &tenant_id,
                &repository_id,
                &node_id,
                &mut store,
            )
            .await,
        );
        assert_eq!(
            lifecycle,
            v1::SupervisorFrameReceipt {
                operation: v1::SupervisorFrameOperation::Lifecycle as i32,
                supervisor_id: supervisor_id.clone(),
                session_id: session_id.clone(),
                idempotent_replay: false,
                projection_advanced: true,
                accepted_outbox_sequence: None,
            }
        );

        let replay = supervisor_receipt(
            handle_authenticated_frame(
                lifecycle_frame,
                &tenant_id,
                &repository_id,
                &node_id,
                &mut store,
            )
            .await,
        );
        assert_eq!(
            replay,
            v1::SupervisorFrameReceipt {
                operation: v1::SupervisorFrameOperation::Lifecycle as i32,
                supervisor_id: supervisor_id.clone(),
                session_id: session_id.clone(),
                idempotent_replay: true,
                projection_advanced: false,
                accepted_outbox_sequence: None,
            }
        );
        assert_eq!(
            store
                .list_sessions(&tenant_id, &repository_id, &supervisor_id)
                .await
                .expect("read persisted supervisor session")[0]
                .session
                .state,
            ContractWorkerState::Paused
        );
        assert_eq!(
            store
                .lifecycle_history(&tenant_id, &repository_id, &session_id)
                .await
                .expect("read persisted lifecycle history")
                .len(),
            1
        );
    }
}
